  {"name":"Cassava (Muhogo)","category":"vegetable","subcategory":"root vegetable","water_requirement":"low","maturity_days":270,"rainfall_min_mm":300,"rainfall_max_mm":1200,"altitude_min_m":0,"altitude_max_m":1500,"suitable_aez":["Dry areas, coastal region and western Kenya"],"soil_types":["sandy loam","loam","sandy soils","any well-drained soil"],"planting_months":["March","April","October","November"],"description":"Very drought-tolerant starchy root crop. Staple food in coastal and western Kenya. Can stay in ground as food reserve.","care_tips":"Use healthy stem cuttings from mosaic-free plants. Plant at 1m x 1m spacing. Very little fertilizer needed. Can harvest at 9-18 months. Can leave in ground for later.","expected_yield":"8,000-25,000 kg per acre","market_price_ksh":"10-30 per kg fresh, 60-100 per kg dry","diseases":["Cassava Mosaic Virus","Cassava Brown Streak Virus","Cassava Whitefly","Mealybug"],"best_counties":["Kilifi","Kwale","Mombasa","Siaya","Homa Bay","Busia","Migori","Tana River"],"varieties":[{"name":"MM96/4271","type":"improved","maturity_days":270,"notes":"Mosaic resistant. High starch. Popular coast variety."},{"name":"Tajirika","type":"improved","maturity_days":240,"notes":"High yield. Early harvest. Virus resistant."},{"name":"Karembo","type":"improved","maturity_days":270,"notes":"Low HCN — safe sweet type. Good cooking quality."}]},

  {"name":"Carrots (Karoti)","category":"vegetable","subcategory":"root vegetable","water_requirement":"moderate","maturity_days":90,"rainfall_min_mm":500,"rainfall_max_mm":1200,"altitude_min_m":1200,"altitude_max_m":2500,"suitable_aez":["Cool highland and medium altitude areas"],"soil_types":["deep sandy loam","loam","stone-free deep soils"],"planting_months":["January","June","July","August"],"description":"Popular root vegetable with high demand in urban markets. Good for export too.","care_tips":"Loosen soil deeply before planting. Sow seeds directly, thin to 8cm spacing. Minimal nitrogen fertilizer. Control aphids. Harvest at 3 months.","expected_yield":"4,000-12,000 kg per acre","market_price_ksh":"20-60 per kg","diseases":["Alternaria Blight","Aphids","Root Knot Nematode","Carrot Fly"],"best_counties":["Nyandarua","Nyeri","Meru","Nakuru","Laikipia","Murang'a"],"varieties":[{"name":"Chantenay","type":"open pollinated","maturity_days":90,"notes":"Most popular in Kenya. Blunt tip. Good for heavy soils."},{"name":"Nantes","type":"open pollinated","maturity_days":85,"notes":"Cylindrical smooth shape. High quality."},{"name":"Kuroda","type":"open pollinated","maturity_days":92,"notes":"Heat tolerant. Good for medium altitude areas."}]},

  {"name":"Peas (Njegere)","category":"vegetable","subcategory":"pod vegetable","water_requirement":"moderate","maturity_days":70,"rainfall_min_mm":500,"rainfall_max_mm":1200,"altitude_min_m":1400,"altitude_max_m":2500,"suitable_aez":["Cool highland areas"],"soil_types":["loam","sandy loam","well-drained fertile soils"],"planting_months":["June","July","August","January"],"description":"Cool season crop with very high export value as snow peas and sugar snaps to Europe.","care_tips":"Inoculate seeds. Provide trellis for climbing types. Control powdery mildew with sulfur fungicide. Pick at tender young stage for fresh or export market.","expected_yield":"2,000-6,000 kg per acre","market_price_ksh":"60-150 per kg fresh","diseases":["Powdery Mildew","Downy Mildew","Ascochyta Blight","Thrips"],"best_counties":["Nyandarua","Nakuru","Nyeri","Murang'a","Kirinyaga","Laikipia"],"varieties":[{"name":"Oregon Sugar Pod","type":"snow pea","maturity_days":65,"notes":"Snow pea type. Very high export value to Europe."},{"name":"Sugar Snap","type":"snap pea","maturity_days":70,"notes":"Edible pod. Premium market to hotels and export."},{"name":"Meteor","type":"dry pea","maturity_days":75,"notes":"Dwarf variety. Dry pea. Good yields."}]},

  {"name":"Bell Pepper/Capsicum (Pilipili Hoho)","category":"vegetable","subcategory":"fruit vegetable","water_requirement":"moderate","maturity_days":80,"rainfall_min_mm":500,"rainfall_max_mm":1200,"altitude_min_m":800,"altitude_max_m":2000,"suitable_aez":["Medium altitude areas with irrigation"],"soil_types":["loam","sandy loam","well-drained fertile soils"],"planting_months":["January","February","August","September"],"description":"High-value vegetable sold in green, red, yellow and orange colors. Export and local hotel market.","care_tips":"Transplant at 5 weeks. Stake plants. Drip irrigation works best. Apply calcium fertilizer for blossom end rot. Harvest at green stage or wait for color.","expected_yield":"8,000-20,000 kg per acre","market_price_ksh":"50-200 per kg","diseases":["Bacterial Spot","Phytophthora Root Rot","Anthracnose","Thrips","Aphids"],"best_counties":["Naivasha","Kajiado","Nakuru","Murang'a","Meru","Kiambu"],"varieties":[{"name":"California Wonder","type":"open pollinated","maturity_days":80,"notes":"Large blocky fruits. Classic green turning to red."},{"name":"Star Fire F1","type":"hybrid","maturity_days":75,"notes":"High yield. Disease resistant. Good for export."},{"name":"Aristotle F1","type":"hybrid","maturity_days":72,"notes":"Large fruits. Excellent shelf life. Good for hotels."}]},

  {"name":"French Beans (Maharage ya Kizungu)","category":"vegetable","subcategory":"pod vegetable","water_requirement":"moderate","maturity_days":55,"rainfall_min_mm":500,"rainfall_max_mm":1200,"altitude_min_m":1200,"altitude_max_m":2200,"suitable_aez":["Highland and medium altitude areas"],"soil_types":["loam","sandy loam","well-drained fertile soils"],"planting_months":["January","February","March","August","September"],"description":"Kenya's biggest export vegetable. Air-freighted to Europe daily. Very high income per acre.","care_tips":"Direct sow seeds. Use drip irrigation. Pick pods at pencil thickness every 2 days. Export standards require 8-12cm long pods with no defects. Cold storage chain essential.","expected_yield":"2,500-6,000 kg per acre","market_price_ksh":"80-200 per kg","diseases":["Angular Leaf Spot","Bean Rust","Halo Blight","Bean Fly","Thrips"],"best_counties":["Naivasha","Kirinyaga","Murang'a","Nakuru","Meru","Laikipia"],"varieties":[{"name":"Amy","type":"round pod","maturity_days":52,"notes":"Bobby bean type. Round pods. Top export variety."},{"name":"Paulista","type":"flat pod","maturity_days":55,"notes":"Flat pod. High yield. Very popular."},{"name":"Teresa","type":"round pod","maturity_days":55,"notes":"Round straight pod. Export grade quality."}]},

  {"name":"Eggplant/Brinjal (Biringanya)","category":"vegetable","subcategory":"fruit vegetable","water_requirement":"moderate","maturity_days":75,"rainfall_min_mm":400,"rainfall_max_mm":1200,"altitude_min_m":0,"altitude_max_m":1800,"suitable_aez":["Coastal and medium altitude areas"],"soil_types":["loam","sandy loam","clay loam"],"planting_months":["January","March","August","October"],"description":"Popular in coastal Kenya and urban areas. Asian varieties command high export price.","care_tips":"Transplant at 4-5 weeks. Stake plants. Spray for mites and aphids. Pick when skin is still shiny before seeds harden inside.","expected_yield":"8,000-20,000 kg per acre","market_price_ksh":"30-80 per kg","diseases":["Phomopsis Blight","Bacterial Wilt","Spider Mites","Aphids"],"best_counties":["Mombasa","Kilifi","Kwale","Nairobi urban","Kiambu","Meru"],"varieties":[{"name":"Black Beauty","type":"open pollinated","maturity_days":75,"notes":"Classic large purple variety. Local market favorite."},{"name":"Long Purple","type":"Asian type","maturity_days":78,"notes":"Long slender shape. Export market to Asian restaurants."}]},

  # FRUITS
  {"name":"Mango (Embe)","category":"fruit","subcategory":"tropical fruit","water_requirement":"low","maturity_days":365,"rainfall_min_mm":500,"rainfall_max_mm":1200,"altitude_min_m":0,"altitude_max_m":1500,"suitable_aez":["Hot dry lowland and coastal areas"],"soil_types":["sandy loam","loam","deep well-drained soils"],"planting_months":["March","April","October"],"description":"Kenya's most important export fruit. Huge variety range for local and export markets. Billions earned annually.","care_tips":"Plant trees 10x10m spacing. Prune for good shape. Apply NPK fertilizer annually. Spray for fruit fly with Malathion. Thin fruits for larger size.","expected_yield":"5,000-20,000 kg per acre from mature trees","market_price_ksh":"20-100 per kg","diseases":["Mango Anthracnose","Powdery Mildew","Fruit Fly","Scale Insects","Stem End Rot"],"best_counties":["Makueni","Machakos","Kitui","Kilifi","Kwale","Mombasa","Tana River","Embu","Meru"],"varieties":[{"name":"Apple Mango","type":"local","maturity_days":365,"notes":"Most popular in Kenya. Red skin. Very sweet. High local demand."},{"name":"Ngowe","type":"local coastal","maturity_days":330,"notes":"Long yellow-green coastal variety. Excellent flavor."},{"name":"Kent","type":"export","maturity_days":365,"notes":"EU export variety. Large. Low fiber. Long shelf life."},{"name":"Tommy Atkins","type":"export","maturity_days":365,"notes":"Red export mango. Very long shelf life. Mild flavor."},{"name":"Keitt","type":"export late","maturity_days":380,"notes":"Late season variety. Green skin when ripe. Low fiber. Export grade."},{"name":"Sabine","type":"local","maturity_days":350,"notes":"Heavy bearer. Popular in Makueni county."}]},

  {"name":"Avocado (Parachichi)","category":"fruit","subcategory":"tropical fruit","water_requirement":"moderate","maturity_days":540,"rainfall_min_mm":800,"rainfall_max_mm":1600,"altitude_min_m":1000,"altitude_max_m":2000,"suitable_aez":["Highland and medium altitude areas"],"soil_types":["deep loam","volcanic loam","well-drained sandy loam"],"planting_months":["March","April","October"],"description":"Fastest growing export crop in Kenya. Massive global demand. Billions exported to Europe and Asia annually.","care_tips":"Plant A-type and B-type varieties together for cross-pollination. Space 5x5m or 7x7m. Apply NPK fertilizer. Never let water sit around roots. Harvest based on oil content or number of days after flowering.","expected_yield":"5,000-20,000 kg per acre from mature trees","market_price_ksh":"30-150 per kg","diseases":["Phytophthora Root Rot","Anthracnose","Scale Insects","Thrips"],"best_counties":["Murang'a","Nakuru","Meru","Embu","Kirinyaga","Nyeri","Kiambu","Kericho","Bomet"],"varieties":[{"name":"Hass","type":"export premium","maturity_days":540,"notes":"World's #1 export avocado. Purple-black skin. Creamy flesh. Premium EU market price."},{"name":"Fuerte","type":"export","maturity_days":540,"notes":"Green pear shape. Long shelf life. Good B-type pollinator for Hass."},{"name":"Jumbo","type":"local market","maturity_days":480,"notes":"Very large green fruit for local market. High yield."},{"name":"Puebla","type":"local","maturity_days":490,"notes":"Oval green variety. Good local market price."},{"name":"G6","type":"export","maturity_days":540,"notes":"High oil content. Approved by KEPHIS for export."}]},

  {"name":"Banana (Ndizi)","category":"fruit","subcategory":"tropical fruit","water_requirement":"high","maturity_days":270,"rainfall_min_mm":900,"rainfall_max_mm":2000,"altitude_min_m":0,"altitude_max_m":1800,"suitable_aez":["Medium altitude warm and sub-humid areas"],"soil_types":["deep loam","alluvial","clay loam","volcanic loam"],"planting_months":["March","April","October"],"description":"Year-round fruit crop. Very important for food security and farm income. Multiple uses including cooking.","care_tips":"Use tissue culture plantlets or clean suckers from disease-free mother plants. Space 3x3m. Apply heavy mulch around base. Remove excess suckers — keep only 1 main and 1 follower. Apply NPK fertilizer and manure regularly.","expected_yield":"10,000-30,000 kg per acre per year","market_price_ksh":"10-30 per finger or bunch","diseases":["Banana Xanthomonas Wilt (BXW) — very serious","Fusarium Wilt (Panama disease)","Black Sigatoka leaf disease","Banana Weevil","Root Knot Nematode"],"best_counties":["Meru","Embu","Murang'a","Kirinyaga","Tana River","Kilifi","Homa Bay","Kisii"],"varieties":[{"name":"Williams","type":"dessert","maturity_days":270,"notes":"Tissue culture variety. High yield. Good for supermarkets."},{"name":"Giant Cavendish","type":"dessert","maturity_days":280,"notes":"Large bunches. Popular in Meru. Good local markets."},{"name":"Sukari Ndizi","type":"apple banana","maturity_days":300,"notes":"Small sweet fingers. Premium price in Nairobi and cities."},{"name":"Muraru/Matoke","type":"cooking banana","maturity_days":270,"notes":"Cooking banana — high starch. Very popular in western Kenya."}]},

  {"name":"Passion Fruit (Maracuya)","category":"fruit","subcategory":"vine fruit","water_requirement":"moderate","maturity_days":270,"rainfall_min_mm":700,"rainfall_max_mm":1400,"altitude_min_m":1000,"altitude_max_m":2200,"suitable_aez":["Highland and medium altitude areas"],"soil_types":["loam","sandy loam","well-drained fertile soils"],"planting_months":["March","April","September","October"],"description":"Fast-growing climbing fruit. Very high juice demand from factories. Good quick income crop.","care_tips":"Build a strong trellis 3m high. Space plants 3x3m. Prune after each season. Spray for Phytophthora root disease. Harvest when fruit skin turns purple or yellow.","expected_yield":"8,000-20,000 kg per acre per year","market_price_ksh":"30-80 per kg","diseases":["Passion Fruit Woodiness Virus — very serious","Phytophthora Root Rot","Brown Spot","Septoria Spot"],"best_counties":["Murang'a","Nakuru","Nyeri","Meru","Kirinyaga","Embu","Nandi","Bomet"],"varieties":[{"name":"Purple Passion","type":"local","maturity_days":270,"notes":"Most common. Sweet-acidic flavor. Good for juice and fresh eating."},{"name":"Yellow Passion","type":"hybrid","maturity_days":250,"notes":"More vigorous. Higher yield. More acidic — juice factories prefer this."},{"name":"Frederick","type":"hybrid","maturity_days":260,"notes":"Virus tolerant. High yield. Popular with juice factories."}]},

  {"name":"Papaya/Pawpaw (Papai)","category":"fruit","subcategory":"tropical fruit","water_requirement":"moderate","maturity_days":270,"rainfall_min_mm":500,"rainfall_max_mm":1500,"altitude_min_m":0,"altitude_max_m":1600,"suitable_aez":["Warm lowland and medium altitude areas"],"soil_types":["loam","sandy loam","well-drained soils","alluvial"],"planting_months":["January","February","March","September"],"description":"Fast-maturing fruit tree. Bears fruit year-round after first harvest. Good steady income for small farms.","care_tips":"Plant 3 seeds per hole then thin to 1 plant. Space 3x3m. Apply NPK fertilizer monthly. Ensure excellent drainage — papaya hates waterlogged roots. Harvest when skin starts turning yellow.","expected_yield":"20,000-50,000 kg per acre per year","market_price_ksh":"15-50 per kg","diseases":["Papaya Ring Spot Virus — use resistant varieties","Phytophthora Root Rot","Anthracnose","Spider Mites","Fruit Fly"],"best_counties":["Mombasa","Kilifi","Kwale","Tana River","Machakos","Embu","Meru","Kisumu","Siaya"],"varieties":[{"name":"Solo","type":"hybrid","maturity_days":270,"notes":"Small fruits. Self-fruitful. High quality orange flesh."},{"name":"Red Royal F1","type":"hybrid","maturity_days":250,"notes":"Red-orange flesh. High sugar content. Good yield."},{"name":"Sunrise Solo","type":"hybrid","maturity_days":260,"notes":"Popular export variety. Pear-shaped. Premium quality."}]},

  {"name":"Watermelon (Tikiti Maji)","category":"fruit","subcategory":"vine fruit","water_requirement":"moderate","maturity_days":85,"rainfall_min_mm":300,"rainfall_max_mm":900,"altitude_min_m":0,"altitude_max_m":1600,"suitable_aez":["Hot dry lowland and semi-arid areas"],"soil_types":["sandy loam","sandy soils","loam"],"planting_months":["January","February","August","September"],"description":"Fast-maturing vine crop with high demand in hot areas and urban markets. Good return per acre.","care_tips":"Sow 3 seeds per hole then thin to 1 plant. Space 2x2m. Apply NPK fertilizer. Control aphids. Thump fruit to test ripeness. Harvest about 30 days after flowering.","expected_yield":"8,000-25,000 kg per acre","market_price_ksh":"20-60 per kg","diseases":["Powdery Mildew","Cucumber Mosaic Virus","Fruit Fly","Root Knot Nematode","Damping Off"],"best_counties":["Makueni","Kitui","Kajiado","Narok","Kilifi","Kwale","Tana River"],"varieties":[{"name":"Crimson Sweet","type":"open pollinated","maturity_days":80,"notes":"Classic striped watermelon. Red flesh. Very popular."},{"name":"Sugar Baby","type":"open pollinated","maturity_days":75,"notes":"Small round type. Early harvest. Very sweet."},{"name":"Charleston Gray","type":"open pollinated","maturity_days":85,"notes":"Oblong shape. Gray-green skin. Very large fruits."},{"name":"Sukari F1","type":"hybrid","maturity_days":78,"notes":"High yield. Very sweet flesh. Disease resistant."}]},

  {"name":"Pineapple (Nanasi)","category":"fruit","subcategory":"tropical fruit","water_requirement":"low","maturity_days":540,"rainfall_min_mm":600,"rainfall_max_mm":1500,"altitude_min_m":0,"altitude_max_m":1500,"suitable_aez":["Warm and coastal areas"],"soil_types":["sandy loam","loam","well-drained slightly acidic soils"],"planting_months":["March","April","October"],"description":"Year-round crop once established. Fresh market eating and juice processing. Good coastal income.","care_tips":"Plant suckers or crowns. Space 30x30cm in double rows. Apply urea fertilizer. Can force flowering with Ethephon hormone. Harvest 15-17 months after planting.","expected_yield":"15,000-40,000 kg per acre","market_price_ksh":"20-60 per fruit","diseases":["Mealybug Wilt Virus","Phytophthora Heart Rot","Fusarium Wilt","Scale Insects"],"best_counties":["Kilifi","Kwale","Tana River","Mombasa","Thika (Kiambu)","Kakamega"],"varieties":[{"name":"Smooth Cayenne","type":"commercial","maturity_days":540,"notes":"Processing type. High juice content. Factory preferred."},{"name":"Queen","type":"local","maturity_days":500,"notes":"Small sweet fresh market fruit. Good eating flavor."},{"name":"MD2 (Gold)","type":"export","maturity_days":540,"notes":"Export standard. Low acid. Golden yellow flesh."}]},

  {"name":"Strawberry (Stroberri)","category":"fruit","subcategory":"berry","water_requirement":"high","maturity_days":90,"rainfall_min_mm":700,"rainfall_max_mm":1400,"altitude_min_m":1500,"altitude_max_m":2500,"suitable_aez":["Cool highland areas"],"soil_types":["sandy loam","loam","well-drained slightly acidic soils"],"planting_months":["June","July","August","September"],"description":"Very high-value berry fruit for supermarkets, hotels and export. Growing demand especially in Nairobi.","care_tips":"Plant on raised beds with mulch covering. Use drip irrigation. Remove runners regularly. Spray for grey mold disease. Harvest daily when fully red. Cold chain essential for export.","expected_yield":"3,000-8,000 kg per acre per season","market_price_ksh":"200-600 per kg","diseases":["Grey Mould (Botrytis)","Red Stele Root Rot","Spider Mites","Verticillium Wilt","Aphids"],"best_counties":["Nyandarua","Nyeri","Murang'a","Nakuru","Kericho","Bomet","Elgeyo-Marakwet"],"varieties":[{"name":"Chandler","type":"open pollinated","maturity_days":90,"notes":"Popular in Kenya. Firm fruit. Good shelf life. High yield."},{"name":"Selva","type":"everbearing","maturity_days":85,"notes":"Consistent production throughout season. Good flavor."},{"name":"Camarosa","type":"open pollinated","maturity_days":88,"notes":"Large firm fruits. Export quality. High yield."}]},

  {"name":"Orange (Chungwa)","category":"fruit","subcategory":"citrus fruit","water_requirement":"moderate","maturity_days":730,"rainfall_min_mm":600,"rainfall_max_mm":1500,"altitude_min_m":0,"altitude_max_m":1800,"suitable_aez":["Medium altitude and sub-humid areas"],"soil_types":["sandy loam","loam","deep well-drained soils"],"planting_months":["March","April","October"],"description":"Popular citrus fruit for fresh eating and juice. Long-bearing trees with many years of income.","care_tips":"Plant on grafted rootstock. Space 6x6m. Apply NPK fertilizer plus manure. Spray for scale insects and mites. Prune water suckers. Harvest when skin turns orange color.","expected_yield":"10,000-30,000 kg per acre from mature trees","market_price_ksh":"10-30 per fruit","diseases":["Citrus Canker","Tristeza Virus","Scale Insects","Fruit Fly","Greening Disease"],"best_counties":["Murang'a","Machakos","Makueni","Meru","Embu","Kisumu","Nyamira"],"varieties":[{"name":"Washington Navel","type":"seedless","maturity_days":730,"notes":"Seedless variety. Premium fresh market price."},{"name":"Valencia","type":"juice orange","maturity_days":760,"notes":"Best juice orange. High acid. Factory preferred."},{"name":"Hamlin","type":"early season","maturity_days":720,"notes":"Early season. Low acid. Good fresh market variety."}]},

  {"name":"Lemon (Limau ya Ulaya)","category":"fruit","subcategory":"citrus fruit","water_requirement":"moderate","maturity_days":365,"rainfall_min_mm":500,"rainfall_max_mm":1200,"altitude_min_m":0,"altitude_max_m":1500,"suitable_aez":["Dry areas and coastal region"],"soil_types":["sandy loam","loam","well-drained soils"],"planting_months":["March","October"],"description":"Year-round citrus for juice, hotels and restaurants. High demand in tourism industry.","care_tips":"Space 6x6m. Prune for good shape. Spray for scale insects and citrus leaf miner. Harvest when skin turns fully yellow.","expected_yield":"10,000-25,000 kg per acre from mature trees","market_price_ksh":"10-40 per fruit","diseases":["Citrus Canker","Greasy Spot Fungus","Scale Insects","Fruit Fly"],"best_counties":["Kilifi","Kwale","Mombasa","Makueni","Taita-Taveta","Embu"],"varieties":[{"name":"Eureka","type":"commercial","maturity_days":365,"notes":"Year-round bearer. Commercial standard lemon."},{"name":"Lisbon","type":"commercial","maturity_days":365,"notes":"Similar to Eureka. Good yield and fruit quality."}]},

  {"name":"Lime (Ndimu)","category":"fruit","subcategory":"citrus fruit","water_requirement":"moderate","maturity_days":300,"rainfall_min_mm":400,"rainfall_max_mm":1200,"altitude_min_m":0,"altitude_max_m":1400,"suitable_aez":["Hot dry coastal and lowland areas"],"soil_types":["sandy loam","loam","well-drained soils"],"planting_months":["March","October"],"description":"Essential ingredient in coastal Kenyan cuisine and cocktails. Very high demand from restaurants and hotels.","care_tips":"Space 4x4m. Light pruning only. Harvest while still green before color change. Very drought tolerant once established.","expected_yield":"8,000-20,000 kg per acre from mature trees","market_price_ksh":"15-50 per kg","diseases":["Citrus Canker","Scale Insects","Citrus Leaf Miner"],"best_counties":["Mombasa","Kilifi","Kwale","Lamu","Tana River"],"varieties":[{"name":"Mexican/Key Lime","type":"local","maturity_days":300,"notes":"Small aromatic fruit. Most common in Kenya. Essential for coastal food."},{"name":"Persian Lime","type":"seedless","maturity_days":300,"notes":"Seedless and large. Good for export and hotel use."}]},

  {"name":"Tangerine/Mandarin (Chenza)","category":"fruit","subcategory":"citrus fruit","water_requirement":"moderate","maturity_days":730,"rainfall_min_mm":500,"rainfall_max_mm":1200,"altitude_min_m":0,"altitude_max_m":1500,"suitable_aez":["Medium altitude and sub-humid areas"],"soil_types":["sandy loam","loam","well-drained soils"],"planting_months":["March","October"],"description":"Easy-peel citrus very popular with children and urban consumers. Growing market demand.","care_tips":"Similar to orange management. Space 5x5m. Good drainage essential. Harvest when skin turns orange-red.","expected_yield":"8,000-20,000 kg per acre from mature trees","market_price_ksh":"15-40 per fruit","diseases":["Scale Insects","Citrus Canker","Fruit Fly","Leaf Miner"],"best_counties":["Murang'a","Meru","Embu","Machakos","Kilifi","Kisumu"],"varieties":[{"name":"Satsuma","type":"seedless","maturity_days":700,"notes":"Seedless. Early ripening. Very sweet."},{"name":"Dancy","type":"seeded","maturity_days":730,"notes":"Classic mandarin flavor. Good yields."}]},

  {"name":"Guava (Mapera)","category":"fruit","subcategory":"tropical fruit","water_requirement":"low","maturity_days":365,"rainfall_min_mm":400,"rainfall_max_mm":1500,"altitude_min_m":0,"altitude_max_m":1800,"suitable_aez":["All medium altitude and lowland areas"],"soil_types":["sandy loam","loam","clay loam","almost any soil"],"planting_months":["March","October"],"description":"Hardy fruit tree requiring very little care. Good for juice, jam and fresh market. Very high in Vitamin C.","care_tips":"Minimal inputs. Prune lightly for shape and air circulation. Fruit fly control is important. Harvest when fruit feels slightly soft and fragrant.","expected_yield":"10,000-30,000 kg per acre from mature trees","market_price_ksh":"10-40 per kg","diseases":["Fruit Fly","Anthracnose","Wilting disease","Scale Insects"],"best_counties":["Embu","Meru","Machakos","Kilifi","Kwale","Murang'a","Kisii"],"varieties":[{"name":"Apple Guava","type":"white-fleshed","maturity_days":365,"notes":"White flesh. Popular fresh fruit variety."},{"name":"Pink Guava","type":"pink-fleshed","maturity_days":365,"notes":"Pink flesh. Very high Vitamin C. Good for processing."},{"name":"Tropical White","type":"sweet","maturity_days":365,"notes":"Sweet white flesh. Juice factory preferred variety."}]},

  {"name":"Kiwi Fruit","category":"fruit","subcategory":"vine fruit","water_requirement":"high","maturity_days":1095,"rainfall_min_mm":1000,"rainfall_max_mm":1800,"altitude_min_m":1700,"altitude_max_m":2500,"suitable_aez":["Cool highland areas above 1700m"],"soil_types":["deep loam","sandy loam","well-drained slightly acidic soils"],"planting_months":["March","April"],"description":"Emerging premium fruit for Kenya highlands. Very high price in Nairobi supermarkets and hotels. Still early stage of production in Kenya.","care_tips":"Need both male and female plants for fruit set. Build strong trellis at 2m height. Deep drip irrigation needed. Annual pruning is critical. Takes 3-5 years to full production.","expected_yield":"3,000-8,000 kg per acre from mature vines","market_price_ksh":"300-800 per kg","diseases":["Crown Rot","Botrytis Grey Mould","Scale Insects","Bacterial Canker"],"best_counties":["Nyandarua","Nyeri","Murang'a","Nakuru","Kericho"],"varieties":[{"name":"Hayward","type":"green-fleshed","maturity_days":1095,"notes":"Standard green kiwi. Most widely grown globally."},{"name":"Bruno","type":"green-fleshed","maturity_days":1095,"notes":"Elongated shape. Good yields adapting to Kenya highlands."}]},

  {"name":"Jackfruit (Fenesi)","category":"fruit","subcategory":"tropical fruit","water_requirement":"low","maturity_days":730,"rainfall_min_mm":600,"rainfall_max_mm":1500,"altitude_min_m":0,"altitude_max_m":1200,"suitable_aez":["Hot coastal and lowland areas"],"soil_types":["deep loam","sandy loam","alluvial soils","well-drained soils"],"planting_months":["March","October"],"description":"Very large tropical fruit eaten ripe or unripe (as vegetable). Growing urban and vegetarian export market.","care_tips":"Plant 10x10m spacing. Very low maintenance once established. Harvest before fully ripe for distant markets.","expected_yield":"5,000-20,000 kg per acre from mature trees","market_price_ksh":"30-100 per kg","diseases":["Fruit Fly","Anthracnose","Root Rot","Scale Insects"],"best_counties":["Kilifi","Kwale","Mombasa","Tana River","Embu","Meru"],"varieties":[{"name":"J31","type":"improved","maturity_days":730,"notes":"High quality sweet flesh. Large fruit size."},{"name":"J33","type":"improved","maturity_days":720,"notes":"Firm flesh. Good for processing into chips."}]},

  {"name":"Plum (Plamu)","category":"fruit","subcategory":"stone fruit","water_requirement":"moderate","maturity_days":730,"rainfall_min_mm":600,"rainfall_max_mm":1200,"altitude_min_m":1600,"altitude_max_m":2400,"suitable_aez":["Cool highland areas that experience cold winters"],"soil_types":["deep loam","sandy loam","well-drained soils"],"planting_months":["June","July"],"description":"Cool highland stone fruit with growing demand in urban supermarkets. Needs cold temperatures to fruit.","care_tips":"Needs cold nights in winter for rest period. Prune annually after harvest. Need cross-pollination — plant 2 varieties. Thin fruits for bigger size.","expected_yield":"4,000-12,000 kg per acre","market_price_ksh":"100-300 per kg","diseases":["Brown Rot","Plum Pox Virus","Scale Insects","Aphids"],"best_counties":["Nyandarua","Nyeri","Murang'a","Nakuru","Laikipia highlands"],"varieties":[{"name":"Methley","type":"self-fertile","maturity_days":730,"notes":"Self-fruitful. Early ripening. Low chilling hours needed."},{"name":"Santa Rosa","type":"improved","maturity_days":760,"notes":"Large attractive fruits. Good flavor. Most popular."}]},

  {"name":"Peach (Pichi)","category":"fruit","subcategory":"stone fruit","water_requirement":"moderate","maturity_days":730,"rainfall_min_mm":600,"rainfall_max_mm":1200,"altitude_min_m":1500,"altitude_max_m":2400,"suitable_aez":["Cool highland areas"],"soil_types":["deep loam","sandy loam","well-drained soils"],"planting_months":["June","July"],"description":"Highland stone fruit. Good supermarket price. Needs cold winters to set fruit.","care_tips":"Annual pruning is absolutely essential for good yield. Thin fruitlets at marble size. Spray for brown rot before harvest. 2-3 years to first production.","expected_yield":"4,000-10,000 kg per acre","market_price_ksh":"100-350 per kg","diseases":["Peach Leaf Curl","Brown Rot","Bacterial Canker","Scale Insects"],"best_counties":["Nyandarua","Nyeri","Murang'a","Nakuru","Elgeyo-Marakwet"],"varieties":[{"name":"Flordaprince","type":"low-chill","maturity_days":730,"notes":"Low chilling hours needed. Good for Kenyan highlands."},{"name":"Earligrande","type":"very early","maturity_days":720,"notes":"Very early season variety. Good yields."}]},

  {"name":"Grapes (Zabibu)","category":"fruit","subcategory":"vine fruit","water_requirement":"moderate","maturity_days":730,"rainfall_min_mm":400,"rainfall_max_mm":900,"altitude_min_m":1200,"altitude_max_m":2000,"suitable_aez":["Medium altitude Rift Valley and semi-arid areas"],"soil_types":["deep loam","sandy loam","well-drained soils","alkaline soil is fine"],"planting_months":["June","July"],"description":"Wine and table grapes are possible in Kenya's Rift Valley. A small but growing wine industry exists.","care_tips":"Trellising system is essential. Annual pruning critical. Use drip irrigation. Spray for powdery mildew regularly. Takes 3 years to first production.","expected_yield":"4,000-15,000 kg per acre","market_price_ksh":"150-400 per kg table grapes, winery contract pricing for wine grapes","diseases":["Powdery Mildew","Downy Mildew","Grey Mould","Scale Insects","Phomopsis"],"best_counties":["Naivasha","Nakuru","Laikipia","Kajiado","Baringo"],"varieties":[{"name":"Cardinal","type":"red table","maturity_days":730,"notes":"Red table grape. Popular in Naivasha area."},{"name":"Crimson Seedless","type":"seedless table","maturity_days":730,"notes":"Seedless variety. Premium supermarket price."},{"name":"Chenin Blanc","type":"white wine","maturity_days":730,"notes":"White wine grape used by Kenyan wineries."}]},

  {"name":"Blueberry","category":"fruit","subcategory":"berry","water_requirement":"moderate","maturity_days":1095,"rainfall_min_mm":700,"rainfall_max_mm":1500,"altitude_min_m":1500,"altitude_max_m":2200,"suitable_aez":["Cool highland areas with acidic soils"],"soil_types":["acidic sandy loam","peat-amended soil — soil must be pH 4.5-5.5"],"planting_months":["March","April","September"],"description":"Emerging premium export berry with major demand from EU and Middle East markets. Very profitable niche crop.","care_tips":"Must acidify soil to pH 4.5-5.5 first — very important. Use drip irrigation with slightly acidified water. Growing under net tunnels is ideal. Prune old wood annually. Takes 3 years before good harvests.","expected_yield":"2,000-6,000 kg per acre","market_price_ksh":"500-1,500 per kg","diseases":["Mummy Berry disease","Botrytis Grey Mould","Stem Blight","Aphids"],"best_counties":["Nyandarua","Nyeri","Murang'a","Nakuru","Kericho","Bomet"],"varieties":[{"name":"Duke","type":"highbush","maturity_days":1095,"notes":"Early season. High yield. Export standard quality."},{"name":"Bluecrop","type":"highbush","maturity_days":1095,"notes":"Mid-season. Most widely grown globally. Good flavor."}]},

  {"name":"Tamarind (Ukwaju)","category":"fruit","subcategory":"tropical fruit","water_requirement":"low","maturity_days":2190,"rainfall_min_mm":250,"rainfall_max_mm":800,"altitude_min_m":0,"altitude_max_m":1000,"suitable_aez":["Very dry arid and coastal areas"],"soil_types":["sandy loam","clay","rocky soils","almost any soil"],"planting_months":["March","October"],"description":"Extremely drought-hardy tree. Pods used in cooking, juice, sweets and beverages. Very long-lived income tree for future generations.","care_tips":"Once established needs almost no care. Survives severe drought. Harvest pods when they turn brown and dry naturally on the tree.","expected_yield":"1,000-5,000 kg per acre from mature trees","market_price_ksh":"50-150 per kg","diseases":["Very few pests. Leaf webber caterpillar occasionally."],"best_counties":["Kilifi","Kwale","Mombasa","Tana River","Garissa","Makueni","Kitui"],"varieties":[{"name":"Local Ukwaju","type":"sour","maturity_days":2190,"notes":"Traditional sour type. Very high food industry demand."},{"name":"Sweet Tamarind","type":"sweet","maturity_days":2190,"notes":"Low acid sweet type. For fresh eating. Hotels and export."}]},

  {"name":"Coconut (Nazi)","category":"fruit","subcategory":"tropical nut","water_requirement":"moderate","maturity_days":2555,"rainfall_min_mm":1000,"rainfall_max_mm":2000,"altitude_min_m":0,"altitude_max_m":600,"suitable_aez":["Hot humid coastal strip only"],"soil_types":["sandy loam","sandy soils","coastal sandy soils"],"planting_months":["March","October"],"description":"Iconic coastal tree. All parts used — water, flesh, oil, fiber, shell. Year-round income from mature trees.","care_tips":"Plant seedlings from selected mother trees. Space 9x9m in triangular pattern. Apply potassium-rich fertilizer. Takes 7-10 years to first harvest. Remove dried fronds. Harvest when nuts turn brown.","expected_yield":"50-200 nuts per tree per year","market_price_ksh":"30-80 per nut, 200-400 per liter coconut oil","diseases":["Lethal Yellowing Disease — very serious","Rhinoceros Beetle","Coconut Bug","Root Wilt"],"best_counties":["Kilifi","Kwale","Mombasa","Lamu","Tana River"],"varieties":[{"name":"East African Tall","type":"tall traditional","maturity_days":2555,"notes":"Traditional coastal variety. Hardy and long-lived. Best for local conditions."},{"name":"Malayan Dwarf","type":"dwarf","maturity_days":1825,"notes":"Early bearing dwarf. More resistant to lethal yellowing disease."}]},

  {"name":"Cashew Nuts (Korosho)","category":"fruit","subcategory":"tropical nut","water_requirement":"low","maturity_days":1825,"rainfall_min_mm":600,"rainfall_max_mm":1500,"altitude_min_m":0,"altitude_max_m":800,"suitable_aez":["Hot dry coastal and lowland areas"],"soil_types":["sandy loam","sandy soils","light well-drained soils"],"planting_months":["March","October"],"description":"Important coastal export nut crop. Kenya exports raw and processed cashews. Good long-term income.","care_tips":"Very drought tolerant once established. Space 10x10m. Minimal fertilizer. Harvest fallen nuts daily during season. Dry in sun before storage. Shell processing adds much more value.","expected_yield":"300-800 kg per acre from mature trees","market_price_ksh":"100-250 per kg raw nuts","diseases":["Cashew Anthracnose","Powdery Mildew","Tea Mosquito Bug","Stem Borer"],"best_counties":["Kilifi","Kwale","Mombasa","Lamu","Tana River"],"varieties":[{"name":"Local Coastal Cashew","type":"local","maturity_days":1825,"notes":"Traditional variety well-adapted to Kenya coast. Good nut quality."},{"name":"CPCRI 1","type":"improved","maturity_days":1825,"notes":"Higher yield improved variety. Early bearing."}]},

  # CASH CROPS
  {"name":"Tea (Chai)","category":"cash crop","subcategory":"beverage crop","water_requirement":"high","maturity_days":1095,"rainfall_min_mm":1200,"rainfall_max_mm":2500,"altitude_min_m":1400,"altitude_max_m":2700,"suitable_aez":["High rainfall highland areas — above 1400m altitude"],"soil_types":["deep volcanic loam","acidic soils pH 4.5-5.5","peaty clay loam"],"planting_months":["March","April","September","October"],"description":"Kenya's largest export crop. The most important highland cash crop. Millions of smallholder farmers depend on tea income.","care_tips":"Plant cuttings in polythene nursery bags first. Bring into production over 3 years by pruning down. Pluck 2-leaf-and-bud every 7-10 days. Apply CAN and NPK fertilizer at recommended rates. Prune every 3-4 years for rejuvenation.","expected_yield":"2,000-4,000 kg per acre of made tea","market_price_ksh":"25-45 per kg green leaf to factory","diseases":["Blister Blight fungus","Red Spider Mite","Tea Mosquito Bug","Root Rot","Looper Caterpillar"],"best_counties":["Kericho","Bomet","Nandi","Kisii","Nyamira","Murang'a","Nyeri","Meru","Kakamega"],"varieties":[{"name":"TRFK 6/8","type":"clone","maturity_days":1095,"notes":"Kenya's most popular clone. High yield and very good tea quality."},{"name":"TRFK 303/577","type":"clone","maturity_days":1095,"notes":"High quality tea liquoring. Top choice for premium estates."},{"name":"SFS 150","type":"clone","maturity_days":1095,"notes":"More drought tolerant. Good for areas with variable rainfall."}]},

  {"name":"Coffee (Kahawa)","category":"cash crop","subcategory":"beverage crop","water_requirement":"moderate","maturity_days":1095,"rainfall_min_mm":900,"rainfall_max_mm":1800,"altitude_min_m":1400,"altitude_max_m":2000,"suitable_aez":["Highland coffee belt between 1400-2000m altitude"],"soil_types":["deep volcanic loam","clay loam","well-drained fertile soils"],"planting_months":["March","April","October"],"description":"Kenya AA coffee is world-famous premium quality. Major foreign exchange earner. Smallholder cooperatives manage most production.","care_tips":"Plant seedlings in shade. Apply NPK fertilizer after each harvest season. Prune to single stem system. Spray for Coffee Berry Disease (CBD) with copper-based fungicide. Handpick only fully red ripe cherries — quality is critical.","expected_yield":"200-600 kg per acre of clean coffee","market_price_ksh":"150-400 per kg clean coffee","diseases":["Coffee Berry Disease (CBD) — most serious","Coffee Leaf Rust","Antestia Bug","Coffee Stem Borer","Wilt"],"best_counties":["Nyeri","Murang'a","Kirinyaga","Kiambu","Embu","Meru","Nakuru","Bungoma"],"varieties":[{"name":"Ruiru 11","type":"hybrid","maturity_days":1095,"notes":"CBD resistant compact plant. High yielding. Most popular new variety."},{"name":"Batian","type":"hybrid","maturity_days":1095,"notes":"Rust and CBD resistant. Excellent cup quality. KARI release."},{"name":"SL28","type":"traditional","maturity_days":1095,"notes":"World-famous cup quality. Drought tolerant. Lower yield but premium price."},{"name":"SL34","type":"traditional","maturity_days":1095,"notes":"High yield. Excellent quality. Popular in high rainfall areas."}]},

  {"name":"Sugarcane (Miwa)","category":"cash crop","subcategory":"sugar crop","water_requirement":"high","maturity_days":540,"rainfall_min_mm":1200,"rainfall_max_mm":2000,"altitude_min_m":1000,"altitude_max_m":1700,"suitable_aez":["Western Kenya sub-humid areas"],"soil_types":["clay loam","alluvial soils","sandy loam","black cotton soil"],"planting_months":["March","April","September","October"],"description":"Major income crop for western Kenya farmers. Must be delivered to sugar factories under contract supply.","care_tips":"Space 90cm x 60cm between rows and plants. Apply DAP at planting then CAN fertilizer. Weed 3 times in first 4 months. Burn crop trash before harvest if allowed. Factory contract is required before planting. Harvest at 18-24 months.","expected_yield":"40-80 tonnes per acre","market_price_ksh":"3,500-5,000 per tonne","diseases":["Sugarcane Smut","Ratoon Stunting Disease","Stalk Borer","Termites","Top Borer insect"],"best_counties":["Kakamega","Bungoma","Kisumu","Siaya","Busia","Migori","Nyamira","Trans Nzoia"],"varieties":[{"name":"N14","type":"commercial","maturity_days":540,"notes":"Mumias Sugar standard variety. High sucrose content."},{"name":"Co421","type":"commercial","maturity_days":520,"notes":"High yield. Widely planted in western Kenya."},{"name":"KCB98-21","type":"improved","maturity_days":540,"notes":"KESREF improved variety. Smut disease resistant."}]},

  {"name":"Sunflower (Alizeti)","category":"cash crop","subcategory":"oilseed crop","water_requirement":"low","maturity_days":100,"rainfall_min_mm":350,"rainfall_max_mm":900,"altitude_min_m":700,"altitude_max_m":2000,"suitable_aez":["Medium altitude and semi-arid areas"],"soil_types":["loam","clay loam","sandy loam"],"planting_months":["March","April","October","November"],"description":"Drought-tolerant cash crop for edible oil and protein animal feed cake. Contract farming available with processors.","care_tips":"Space 75x25cm. Avoid too much nitrogen fertilizer. Apply boron spray at flowering stage. Cover with bird-scaring nets at ripening. Harvest when seed head turns brown and dry.","expected_yield":"4-12 bags per acre","market_price_ksh":"4,000-7,000 per 90kg","diseases":["Alternaria Leaf Blight","Sclerotinia Stem Rot","Aphids","Bird damage"],"best_counties":["Nakuru","Machakos","Kitui","Makueni","Baringo","Laikipia","Meru"],"varieties":[{"name":"Sunko","type":"hybrid","maturity_days":95,"notes":"Most popular in Kenya. High oil content. Good yield."},{"name":"PANNAR 7351","type":"hybrid","maturity_days":100,"notes":"High yielding. Disease tolerant variety."},{"name":"Record","type":"open pollinated","maturity_days":105,"notes":"Lower cost seed option. Reliable yields."}]},

  {"name":"Macadamia Nuts","category":"cash crop","subcategory":"nut crop","water_requirement":"moderate","maturity_days":2190,"rainfall_min_mm":700,"rainfall_max_mm":1400,"altitude_min_m":800,"altitude_max_m":1800,"suitable_aez":["Medium altitude and lower highland areas"],"soil_types":["deep loam","sandy loam","well-drained volcanic soils"],"planting_months":["March","April","October"],"description":"Kenya is now the world's top macadamia producer. A long investment but provides income for lifetime and for children.","care_tips":"Buy only grafted trees — seedling trees have poor results. Space 7x7m. Apply NPK fertilizer annually. Takes 6-8 years to full production. Harvest only fallen nuts from ground — don't pick from tree. Dehusk within same day of harvest.","expected_yield":"500-2,000 kg per acre of kernel from mature trees","market_price_ksh":"200-400 per kg in-shell nuts","diseases":["Macadamia Nut Borer insect","Anthracnose fungus","Phytophthora Root Rot","Scale Insects"],"best_counties":["Murang'a","Embu","Meru","Nakuru","Nyeri","Kirinyaga","Kiambu"],"varieties":[{"name":"HAES 814","type":"commercial","maturity_days":2190,"notes":"Early bearing variety. High kernel recovery percentage."},{"name":"HAES 842","type":"commercial","maturity_days":2190,"notes":"High yield. Good shell filling. Most popular choice."},{"name":"HAES 660","type":"commercial","maturity_days":2190,"notes":"Excellent kernel quality. Late season harvest."}]},

  {"name":"Pyrethrum","category":"cash crop","subcategory":"natural insecticide crop","water_requirement":"moderate","maturity_days":365,"rainfall_min_mm":900,"rainfall_max_mm":1400,"altitude_min_m":1800,"altitude_max_m":3000,"suitable_aez":["Cool high altitude areas above 1800m only"],"soil_types":["volcanic loam","clay loam","well-drained fertile soils"],"planting_months":["March","September"],"description":"Natural insecticide extracted from flowers. Grown exclusively in cool highlands. Sold to Pyrethrum Board of Kenya.","care_tips":"Plant root splits 60x60cm spacing. Split plants annually to multiply. Pick flowers when 30% are just open. Dry flowers in shade before delivery to PBK buying center.","expected_yield":"300-600 kg per acre dry flowers","market_price_ksh":"150-250 per kg dry flowers","diseases":["Root Rot","Pyrethrum Aphid","Leaf Miner insect"],"best_counties":["Nakuru","Nyandarua","Meru","Murang'a","Nyeri","Kericho","Uasin Gishu"],"varieties":[{"name":"Py1","type":"improved","maturity_days":365,"notes":"High pyrethrin content. Standard variety for Kenya."},{"name":"Py2","type":"improved","maturity_days":365,"notes":"Very vigorous plant. High yield."}]},

  {"name":"Miraa/Khat (Miraa)","category":"cash crop","subcategory":"stimulant crop","water_requirement":"low","maturity_days":1825,"rainfall_min_mm":400,"rainfall_max_mm":1200,"altitude_min_m":1000,"altitude_max_m":2200,"suitable_aez":["Meru and Tharaka-Nithi highlands"],"soil_types":["red loam","sandy loam","rocky soils"],"planting_months":["March","October"],"description":"Very high-value cash crop unique to Meru and Nyambene Hills. Exported daily by air to UK, Netherlands, Somalia and diaspora markets worldwide.","care_tips":"Extremely drought tolerant. Minimal fertilizer. Harvest young fresh shoots daily for air export market. Very consistent daily income once established. Takes 5 years to full production.","expected_yield":"Very high income — KSh 100,000-500,000 per acre per year","market_price_ksh":"Very variable — high export premium pricing","diseases":["Fusarium Wilt","Scale Insects","Aphids"],"best_counties":["Meru","Tharaka-Nithi","Embu"],"varieties":[{"name":"Meru Miraa","type":"local","maturity_days":1825,"notes":"Traditional Nyambene variety. World-famous quality. Export to UK, Netherlands, Somalia."}]},

