  {"name":"Roses (Waridi)","category":"flower","subcategory":"cut flower","water_requirement":"high","maturity_days":90,"rainfall_min_mm":700,"rainfall_max_mm":1200,"altitude_min_m":1800,"altitude_max_m":2400,"suitable_aez":["Cool highland areas — Naivasha and environs"],"soil_types":["deep loam","sandy loam","clay loam with pH 6-6.5"],"planting_months":["January","February","March","September","October"],"description":"Kenya is the world's top rose exporter. Naivasha is the global rose capital. Billions of stems air-freighted to Europe daily for Valentine's Day and other occasions.","care_tips":"Must grow under shade nets. Use drip irrigation under nets. Space 25x25cm plants. Harvest cycle is 6-7 weeks. Cold room essential after harvest. Spray regularly for mildew and botrytis grey mould.","expected_yield":"150,000-250,000 stems per acre per year","market_price_ksh":"10-50 per stem export auction price","diseases":["Powdery Mildew","Botrytis Grey Mould","Downy Mildew","Spider Mites","Thrips","Aphids"],"best_counties":["Naivasha","Nakuru","Nyandarua","Eldoret","Thika"],"varieties":[{"name":"Freedom","type":"red","maturity_days":90,"notes":"Most popular Kenya export rose. Deep red. 50-60cm stem."},{"name":"Lovely Red","type":"red","maturity_days":88,"notes":"High export demand. Premium quality red rose."},{"name":"Avalanche","type":"white","maturity_days":90,"notes":"Premium white rose. Large head. 60cm stem. Wedding market."},{"name":"Pink Floyd","type":"pink-salmon","maturity_days":90,"notes":"Salmon-pink color. Very popular for Valentine's Day."},{"name":"Duett","type":"bicolor","maturity_days":88,"notes":"Red with white edges. Novelty variety. Premium price."}]},

  {"name":"Carnations (Karafuu ya Maua)","category":"flower","subcategory":"cut flower","water_requirement":"moderate","maturity_days":120,"rainfall_min_mm":600,"rainfall_max_mm":1200,"altitude_min_m":1800,"altitude_max_m":2400,"suitable_aez":["Cool highland areas"],"soil_types":["sandy loam","loam with pH 5.5-6.5"],"planting_months":["January","July"],"description":"Major export cut flower grown under nets in highland Kenya. Important income crop for flower farms.","care_tips":"Grow in net tunnels for wind and pest protection. Space 15x15cm. Pinch growing tip for branching. Harvest cycles of 14 weeks. Temperature control is critical. Cold chain essential.","expected_yield":"80,000-150,000 stems per acre per year","market_price_ksh":"8-30 per stem","diseases":["Fusarium Wilt","Alternaria Leaf Spot","Thrips","Spider Mites","Leaf Miner"],"best_counties":["Naivasha","Nakuru","Nyandarua","Laikipia"],"varieties":[{"name":"Lena","type":"standard red","maturity_days":120,"notes":"Red standard carnation. Very popular EU export market."},{"name":"Pallas","type":"spray pink","maturity_days":110,"notes":"Multi-headed spray type. Pink tones. Good value."}]},

  {"name":"Alstroemeria (Peruvian Lily)","category":"flower","subcategory":"cut flower","water_requirement":"moderate","maturity_days":180,"rainfall_min_mm":700,"rainfall_max_mm":1400,"altitude_min_m":1800,"altitude_max_m":2400,"suitable_aez":["Cool highland areas"],"soil_types":["sandy loam","loam","well-drained fertile soils"],"planting_months":["March","September"],"description":"Lily of the Incas. A growing export flower from Kenya highlands. Long vase life makes it popular in Europe.","care_tips":"Plant rhizomes 30cm deep in soil. Cool temperatures are required. Space 30x30cm. Harvest when 2-3 florets just begin to open.","expected_yield":"60,000-120,000 stems per acre per year","market_price_ksh":"15-40 per stem","diseases":["Botrytis Grey Mould","Root Rot","Thrips"],"best_counties":["Naivasha","Nakuru","Nyandarua"],"varieties":[{"name":"Mixed Colors","type":"hybrid","maturity_days":180,"notes":"Red, orange, yellow, pink, white colors. EU market demand for variety mixes."}]},

